    "5981": "Schließen",
    "6227": "Die Dateien müssen durch KI analysiert werden, um klassifiziert zu werden. Zu viele Dateien können zeitaufwendig sein. Der Arbeitsmodus bestimmt, ob die Analyseergebnisse auf dem Server zwischengespeichert werden.",
