    "6230": "Ihre Analyseergebnisse werden nur lokal gespeichert und nicht auf dem Server zwischengespeichert, um die Datenhoheit zu schützen. Allerdings können Sie nicht von der Geschwindigkeitssteigerung durch den Server-Cache profitieren.",
