    "7683": "Klicken Sie hier, um die KI-Engine-Konfiguration zu öffnen",
    "7684": "Erklärung des Cloud-Sharing-Prinzips",
    "7685": "Betrachten Sie den Schutz der Privatsphäre stets als zentralen Gestaltungsgrundsatz und halten Sie ihn ein",
    "7686": "Lokale Datenpriorität",
    "7687": ", um die Privatsphäre und Sicherheit der Benutzer wirksam zu schützen, und seine technischen Kernprinzipien stimmen logisch mit dem in der Branche üblichen Hash-Mechanismus (Hash) überein.",
    "7688": "In einfachen Worten",
    "7689": ", generiert das System über einen Verschlüsselungsalgorithmus für jede Datei eine eindeutige charakteristische Kennung (Länge 16–128 Zeichen), die der eindeutigen ID der Datei entspricht.",
    "7690": "Generieren Sie diese ID",
    "7691": "Die einzige Voraussetzung",
    "7692": ", speichert der Benutzer die Datei lokal und schließt die Algorithmusberechnung ab. Die Anwendung gibt die Datei-ID nicht an Dritte weiter. Nur mit dieser ID können die Analysedaten der entsprechenden ID vom Server angefordert werden und es gibt keine andere Möglichkeit, diese zu erhalten.",
    "7693": "Sogar drin",
    "7694": "Unter extremen Annahmen",
    "7695": "(Der Server wurde angegriffen), Dritte können nur Dateianalysedaten und entsprechende IDs erhalten, und die ID-Algorithmen verschiedener Plattformen sind völlig unabhängig und haben keine Verbindung zu den Datei-IDs von Plattformen wie Baidu Netdisk und können Originaldateien nicht plattformübergreifend abgleichen.",
    "7696": "Gleichzeitig,",
    "7697": "Der Server speichert nur analytische Daten",
    "7698": ": Einschließlich intelligenter Dateinamen, Tags, Inhaltszusammenfassungen, Bewertungen und Gründe, Metadaten usw., die Sie im Eigenschaftenfenster rechts sehen können. Die Datei selbst wird niemals hochgeladen oder gespeichert.",
