    "9785": "Die täglich neue Großmodellschnittstelle von SenseTime befindet sich derzeit in der öffentlichen Betaphase und bietet ein kostenloses Anrufkontingent.",
    "9787": "Das leistungsstarke Leichtbaumodell von SenseTime",
    "9789": "Das extrem schnelle Argumentationsmodell von SenseTime",
    "9792": "DeepSeek-Schnellinferenzmodell, gehostet von SenseTime",
    "9794": "Melden Sie sich an und erhalten Sie eine 10-Dollar-Testversion, keine Kreditkarte erforderlich. Die Gutschrift ist innerhalb von 3 Monaten gültig. Beinhaltet die Modelle Jamba Large und Jamba Mini.",
    "9795": "Israel",
    "9800": "Alibaba Cloud Bailian (Internationale Version)",
    "9801": "Nach der Registrierung erhält jedes Tongyi Qianwen-Modell 1 Million kostenlose Token mit einer Gültigkeit von 90 Tagen (international/Raum Singapur). Keine Kreditkarte erforderlich.",
    "9803": "Kostenloser „Test“-API-Schlüssel, keine Kreditkarte erforderlich. 1000 API-Aufrufe pro Monat. Nur für nicht-kommerzielle Nutzung.",
    "9804": "Kanada",
    "9816": "Kostenloser „Experimental“-Plan, keine Kreditkarte erforderlich. Ungefähr 1 Milliarde Token pro Monat. Zur Verbesserung des Modells können Stichworte verwendet werden.",
    "9825": "Zhipu KI",
    "9826": "Bietet für immer kostenlose Modelle, keine Kreditkarte erforderlich.",
    "9829": "Kostenlos, keine Kreditkarte erforderlich. Extrem schnelles Denken (ca. 2600 Token/s). Tageslimit von 1 Million Token. 8K-Kontextbeschränkung für kostenlose Dateien. llama3.1-8b wird voraussichtlich am 27. Mai 2026 veraltet sein.",
    "9835": "Täglich 10.000 Neuronen kostenlos. Die kostenlose Version bietet über 50 Modelle.",
    "9841": "Kostenlose Prototyping-Credits für alle GitHub-Benutzer. Enthält über 45 Modelle. Es gibt ein Limit für eine einzelne Anfrage (8K Eingang / 4K Ausgang).",
    "9846": "Kostenlos, keine Kreditkarte erforderlich. Extrem schnelle LPU-Inferenz.",
    "9851": "Stellen Sie kostenlosen Benutzern ein monatliches Inferenzdienstkontingent von 100.000 Malen zur Verfügung. Routen zu Anbietern wie Fireworks, Together, Hyperbolic, Nebius, Novita, DeepInfra und mehr. Unterstützt Tausende von Modellen.",
    "9855": "Kostenloses Modell, keine Kreditkarte erforderlich. „kilo-auto/free“ leitet automatisch zu minimax/minimax-m2.5:free (80 %) und stepfun/step-3.5-flash:free (20 %) weiter.",
    "9857": "Nahtloses API-Gateway. Für den Basiszugang ist keine Registrierung erforderlich. Unterstützt mehr als 30 Modelle. DSGVO-konform.",
    "9858": "VEREINIGTES KÖNIGREICH.",
    "9862": "ModelScope",
    "9863": "Bietet registrierten Benutzern kostenlose API-Inferenzdienste. Sie müssen Ihr Alibaba Cloud-Konto binden und die Authentifizierung mit echtem Namen durchführen.",
    "9868": "Melden Sie sich an und erhalten Sie 1 $ kostenloses Guthaben, keine Kreditkarte erforderlich. Mehr als 60 Open-Source-Modelle sind über eine OpenAI-kompatible API verfügbar. Hauptsitz in der EU.",
    "9869": "Niederlande",
    "9872": "Melden Sie sich an und erhalten Sie ein kostenloses Guthaben in Höhe von 5 $, keine Kreditkarte erforderlich. Souveräner EU-Anbieter mit Rechenzentrum in Norwegen. Keine Geschwindigkeitsbegrenzung, kein Kaltstart.",
    "9874": "Kostenlos mit qualitativen Nutzungsbeschränkungen. Bietet über 400 Modelle aus der Ollama-Bibliothek. Nicht kompatibel mit OpenAI SDK, verwenden Sie [Ollama API](https://docs.ollama.com/cloud).",
    "9877": "OVHcloud KI-Terminal",
    "9878": "Kostenloses anonymes Profil (kein API-Schlüssel, keine Registrierung erforderlich): Begrenzt 2 U/min pro Modell und IP. Hosting von über 40 Open-Source-Gewichtsmodellen in der EU. Kompatibel mit OpenAI SDK.",
    "9882": "Kostenloses tägliches Token-Kontingent, keine Kreditkarte erforderlich. Entwickelt für Rollenspiele und die Erstellung von Geschichten.",
    "9885": "Die Anzahl der Anfragen pro Minute ist auf 20 begrenzt. Wenn die Anfrage in einem kurzen Zeitraum zu schnell ist, wird die Frequenzbegrenzung ausgelöst (Sie müssen 1 Minute warten und es erneut versuchen).",
    "9886": "Singapur",
    "9889": "Das schnelle und effiziente Modell von Sapiens AI unterstützt das Bildverständnis.",
    "9895": "Neuer Cloud-Dienst Agnes AI hinzugefügt, dauerhaft kostenlose API, aus dem Landesinneren erreichbar",
