    "19579": "Enable video search and tag correction (high-dimensional correction)",
    "19580": "Once enabled, high-dimensional correction is automatically performed after the file queue analysis is completed: tags and smart naming are re-calibrated using 2048-dimensional multimodal vectors, unlocking image-based search and natural language video search.",
    "19581": "High-dimensional vector correction is applied to tags, smart file names, and descriptions for more accurate results. This also enables more precise file search, even supporting natural language search for video content. After the file queue analysis is complete, high-dimensional correction is automatically performed, taking approximately 1 second per file;",
    "19582": "Mehdoddemodell WeMM-Embedding 2B für multimodale Embeddings wird geprüft...",
    "19583": "Es wurde nicht erkannt, dass der Firefly AI-Engine läuft; es kann nicht bestätigt werden, ob das multimodale Embeddingsmodell WeMM-Embedding 2B installiert ist. Hochkorrekturen hängen von diesem Modell ab; bitte starten oder installieren Sie zuerst die Firefly AI-Engine.",
