    "20681": "Wiederverwendung von Daten bei erneuter Analyse",
    "20682": "Falls sich die Datei geändert hat, deaktivieren Sie diese Option. Andernfalls wird die Erfassung der Basisinformationen für eine beliebige Datei übersprungen, falls die Basisinformationen bereits vorliegen. Die Basisinformationen umfassen: Dateityp, Thumbnail, Metadaten und Dateiinhalte",
