    "20684": "Beispiel: Merkmalsbeschreibung einer Datei-Gruppe als übergeordnete Einheit: Datei-Gruppen, deren Filenamen eine Zahlenangabe enthalten, z. B. 1.txt, 2.txt, 3.txt",
    "20686": "Erkennt Gesamt-Einheiten wie Serien von Dateien, Tonspur-Alben und Projektverzeichnisse und unterstützt benutzerdefinierte Erkennungsanweisungen für Mindesteinheiten",
    "20687": "Mindesteinheiten-Erkennung aktivieren",
    "20688": "Die folgenden Kategorien werden erzwungenermaßen erkannt, ohne dass sie aktiviert werden müssen: Systemverzeichnisse, Softwareinstallationsverzeichnisse, Projekte, Spiele-Pakete, KI-Datensätze/Modelle, Caches und LFS, virtuelle Umgebungen",
    "20689": "Nach der Aktivierung werden Verzeichnisse, die als Mindesteinheiten erkannt werden, übersprungen, und die Datei-einzeln-Analyse wird unterdrückt",
    "20690": "Serien von Dateien: aufeinanderfolgend nummerierte Dokumente oder Bilder (z. B. 01.jpg, 02.jpg, 03.jpg)",
    "20691": "Audio-Album: Sammlung von Audio-Dateien desselben Albums (z. B. .flac, .mp3)",
    "20692": "Designprojekt: Designprojekt mit Projektdatei und Ressourcenverzeichnis (z. B. .prproj, .aep, .blend)",
    "20693": "Hinweis: Nach dem Deaktivieren werden alle Dateien separat analysiert, geeignet für Szenarien, in denen für jede Datei individuelle Beschreibungen und Tags erstellt werden müssen",
    "20694": "Eingabeaufforderung für die Erkennung minimaler Einheiten",
    "20695": "Erfordert das Aktivieren des Schalter oben, um wirksam zu werden",
    "20696": "Definiert, welche Art von Dateisammlung als eine ganzheitliche Einheit betrachtet werden soll; Justierung des Erkennungsverhaltens des Modells",
