    "21811": "Importieren Sie eine externe, von der KI generierte Verzeichnisstruktur",
    "21812": "Benutzerdefiniertes Verzeichnisbaum",
    "21813": "Was Sie sehen, ist was Sie bekommen · Echtzeitanalyse",
    "21814": "Fügen Sie den vom externen großen Modell generierten Markdown-Verzeichnisbaum ein. Die rechte Seite wird in Echtzeit analysiert. Die erste Zeile unterstützt die automatische Erkennung mit [Name des virtuellen Verzeichnisses: xxxx]",
    "21815": "Schreiben oder fügen Sie den Verzeichnisbaum frei im Markdown-Format ein. Die rechte Seite wird in Echtzeit analysiert und in der Vorschau angezeigt. Sobald Sie zufrieden sind, beginnen Sie mit der Feinabstimmung.",
    "21816": "Kehren Sie zur externen KI-Anleitung zurück",
    "21817": "Wird als Name des endgültigen physischen Ordners verwendet",
    "21818": "Organisationsstrategie und Markdown-Verzeichnisbaum",
    "21819": "Bitte fügen Sie den von der externen KI generierten Verzeichnisbaum direkt ein. Die erste Zeile kann geschrieben werden: Name des virtuellen Verzeichnisses: xxxx\\n- Ordner 1\\n - Unterordner A\\n- Ordner 2",
    "21820": "Bitte geben Sie die Verzeichnisbaumstruktur direkt ein oder fügen Sie sie ein (unterstützt Standard-Markdown-Liste – oder * und Einrückung): \\n- Verzeichnis der obersten Ebene 1\\n - Unterverzeichnis A\\n- Verzeichnis der obersten Ebene 2",
    "21821": "Unterstützt Markdown-Listen (- Verzeichnisnamen), Einrückungen auf Tabulator-/Leerzeichenebene und Baumsymbole (├ └ │)",
    "21822": "Live-Vorschau des Verzeichnisbaums",
    "21823": "Insgesamt {count} Verzeichnisse",
    "21824": "Die Analyse ist fertig und Sie können jederzeit in die Feinabstimmung einsteigen.",
    "21825": "Warten auf die Eingabe eines gültigen Verzeichnisformats",
    "21826": "Derzeit ist keine analysierte Verzeichnisstruktur generiert.",
    "21827": "Bitte geben Sie links die Verzeichnisbaumstruktur im Markdown-Listenformat ein (z. B. Verzeichnis der ersten Ebene). Die Baumstruktur wird rechts in Echtzeit gerendert.",
    "21828": "Echtzeit-Syntaxanalyse abgeschlossen",
    "21829": "Bitte geben Sie mindestens ein gültiges Verzeichnis ein, um fortzufahren",
    "21830": "Nächster Schritt: Feinabstimmung der Verzeichnisstruktur",
    "21831": "Kopieren Sie den Codeblock der zufriedenstellenden Lösung, klicken Sie oben rechts auf [Generiert, Weiter], um die Klassifizierung zu importieren und in Sekundenschnelle abzuschließen.",
    "21832": "Wählen Sie den geeigneten Pfad basierend auf Dateimerkmalen und Organisationsanforderungen und erstellen Sie effizient ein klares und geordnetes Verzeichnissystem.",
    "21833": "Basierend auf der maßgeblichen Karriere- und Lebensrollendatenbank empfiehlt es genau angepasste Standardverzeichnisstrukturen und mehrere Kandidatenpfade.",
    "21834": "Kopieren Sie die Eingabeaufforderungswörter des aktuellen Dateiporträts mit einem Klick in das Planungsverzeichnis Doubao/ChatGPT/Kimi, was einen extrem schnellen Import unterstützt.",
    "21835": "Natives, unbeaufsichtigtes hierarchisches Clustering auf der Geräteseite, sofortige Diagrammausgabe auf Millisekundenebene und Unterstützung für schnelle Wortführung in natürlicher Sprache und Inline-Feinabstimmung.",
    "21837": "Drei Sätze endgültiger, vollständiger hierarchischer Verzeichnisbaumlösungen werden anhand des großen Modells umfassend geplant und können ohne langwierige Schritte direkt verglichen und ausgewählt werden.",
    "21838": "Flexibilität und Freiheit",
    "21839": "Schreiben Sie die Gliederung des Inhaltsverzeichnisses direkt per Hand oder fügen Sie sie im Markdown-Format ein, rechts finden Sie eine Echtzeit-Syntaxanalyse und am Ende eine sekundenschnelle Vektorkategorisierung.",
    "21840": "Die inkrementelle Defragmentierung wird verwendet, um neue Dateien an vorhandene virtuelle Verzeichnisse anzuhängen. Ihr aktueller Arbeitsbereich hat keine virtuellen Verzeichnisse gespeichert. Bitte wählen Sie oben den entsprechenden Organisationsmodus aus, um die virtuellen Verzeichnisse zu vervollständigen und zu speichern.",
    "21849": "Firefly Core Smart Folder muss auf Ihren Ordner \"Downloads\" zugreifen, um Dateien zu organisieren und abzurufen.",
    "21850": "Firefly Core Smart Folders benötigt Zugriff auf Ihren \"Desktop\" -Ordner, um Dateien zu organisieren und abzurufen.",
    "21851": "Firefly Core Smart Folders benötigt Zugriff auf Ihren Ordner \"Dokumente\", um Dateien zu organisieren und abzurufen.",
    "21852": "Firefly Core Smart Folders benötigt Zugriff auf externe Speichergeräte, um Dateien zu organisieren und abzurufen.",
    "21853": "Firefly Core Smart Folders benötigt Zugriff auf freigegebene Netzwerkvolumes, um Dateien zu organisieren und abzurufen.",
    "21855": "Unzureichende Berechtigungen, gehen Sie bitte zu macOS \"Systemeinstellungen-> Datenschutz und Sicherheit-> Dateien und Ordner\", um dieser Anwendung Zugriff auf dieses Verzeichnis zu gewähren: {dirPath}",
    "21856": "Tiefe semantische Ausrichtung...",
