    "21877": "Tiefe semantische Planung dauert lange (es hat {seconds} Sekunden gedauert). Reagiert das lokale Modell langsam, kann es auf externe KI-Planung umgestellt werden.",
    "21878": "Wechseln Sie zu externer KI-Planung",
    "21879": "AI hat tief geplant, 3 Sätze vollständiger hierarchischer Verzeichnisstrukturbäume zu generieren, Klicken Sie, um direkt zu übernehmen und die Feinabstimmung einzugeben, Sie müssen nicht zweimal warten",
    "21880": "Der empfohlene Fertigstellungsplan wurde nicht erhalten.Dies kann daran liegen, dass das lokale große Modell ausgelastet ist oder die Rechenleistung nicht ausreicht.",
    "21881": "Es wird empfohlen, ein Modell über dem Niveau \"Gymnasiast\" zu verwenden, um bessere Ergebnisse zu erzielen. Jeder Plan enthält einen empfohlenen virtuellen Verzeichnisnamen und einen vollständigen hierarchischen Baum.",
