    "22315": "Eingabeaufforderung schließen",
    "22316": "Zum Beispiel: Klassifizierung nach Jahr und Finanzen, Archivierung von Projektdokumenten ...",
    "22320": "Beispiele: Fügen Sie Comedy-Geschichten mehr Punkte hinzu; das Gewicht technischer Indikatoren reduzieren; Die multimodale Inhaltsbeschreibung konzentriert sich auf Charakterbeziehungen, übersetzt als {activeLanguage}",
    "22321": "Beispiel: Intelligente Dateinamen müssen in {activeLanguage} übersetzt werden. Es können maximal 20 Tags generiert werden, und jedes Tag sollte nicht mehr als 2 Wörter umfassen. Mindestens ein Tag muss aus dem Dateinamen extrahiert werden und die anderen müssen aus diesem Satz extrahiert werden: [Glück, Schmerz, Groll,...]",
    "22334": "[Rekonstruktion der KI-Engine] Die integrierte Basis-KI-Engine ist sofort einsatzbereit, mit der optionalen erweiterten Firecore/Cloud-KI-Engine zur Verbesserung der Analyse bei Bedarf.",
    "22335": "[Computerfreundlich mit geringer Konfiguration] Rekonstruieren Sie eine Hochgeschwindigkeits-KI-Architektur basierend auf CPU-Inferenz und laufen Sie reibungslos auf Geräten mit geringem Speicher und ohne unabhängige Grafikkarten",
    "22336": "[Unabhängige Firecore AI Engine] Kann unabhängig vom Hauptprogramm ausgeführt werden, um Anwendungen von Drittanbietern KI-Funktionen bereitzustellen",
    "22337": "[Semantische Multimedia-Suche] Bilder, Audios und Videos unterstützen das Abrufen natürlicher Sprache und durchsuchen Inhalte nach Semantik, Bildern und Stimmen",
    "22338": "[Sprach-zu-Text-ASR] Transkribieren Sie Audio- und Videogespräche schnell in Text, um sie einfach abzurufen und zu archivieren",
    "22339": "[Sprachsynthese TTS] Text-to-Speech, über 50 integrierte Sounds, unterstützt das 3-Sekunden-Sound-Klonen und liest Dokumentromane laut vor",
    "22340": "[Datei-Tag-Upgrade] Erweitern Sie die Fakten-Tag-Typen, die Tags sind genauer und interpretierbarer und der Tag-Baum unterstützt 10 Erweiterungsstufen",
    "22341": "[Creator Material Optimization] Für Designer und Self-Media, spezielle Optimierung der Sortierung von Audio-, Video- und Bildmaterial",
    "22342": "[Erweiterte Erkennung sensibler Inhalte] Identifizieren Sie segmentweise pornografische, gewalttätige, terroristische, politische, beleidigende, blutige und andere illegale Inhalte und deren Unterkategorien",
    "22343": "[Fünf wichtige Stapelsortiermodi] Identitätsentwurf / intelligentes Clustering / externes KI-generiertes Verzeichnis / Dateiableitungsverzeichnisbaum / benutzerdefinierter Verzeichnisbaum, Verarbeitung Tausender Dateien in Sekunden",
    "22344": "[Identity Blueprint (empfohlen)] Wählen Sie Branchenrollen aus, optimieren Sie sie in vier Stufen und klassifizieren Sie alle Dateien in Millisekunden auf der Clientseite",
    "22345": "[Intelligentes Clustering] Endseitiges unbeaufsichtigtes HAC-Clustering, Generierung von Verzeichnisbäumen in Millisekunden, Klassifizierung aller Dateien in Sekunden und Unterstützung der Feinabstimmung in Echtzeit",
    "22346": "[Externes, von der KI generiertes Verzeichnis] ​​Kopieren Sie Eingabeaufforderungswörter mit einem Klick nach Doubao, Kimi, ChatGPT und zeigen Sie die Ergebnisse in Echtzeit in der Vorschau an und organisieren Sie sie",
    "22347": "[Verzeichnisbäume aus Dateien ableiten] Die fortschrittliche KI-Engine gibt jeweils drei Sätze von Verzeichniskandidaten aus und wählt die automatische Klassifizierung aus",
    "22348": "[Angepasster Verzeichnisbaum] Markdown-Verzeichnis einfügen, zweispaltige Echtzeitvorschau erstellen und exklusive Organisationsregeln erstellen",
    "22349": "[Umfassende Optimierung der Benutzeroberfläche] Rekonstruieren Sie die Struktur der Einstellungsseite, fügen Sie eine neue Anleitung und einen neuen Hilfeeinstieg hinzu und gestalten Sie die Bedienung intuitiver.",
    "22350": "In der Schnittstelle tritt eine Ausnahme auf",
    "22351": "Der Schnittstellen-Rendering-Prozess wurde beendet und die Anwendung konnte nicht automatisch fortgesetzt werden. Bitte starten Sie die App neu und versuchen Sie es erneut.",
    "22352": "Abnormale Ursache",
    "22353": "Neu laden",
    "22354": "Die Ressourcen der Anwendungsschnittstelle fehlen (index.html wurde nicht gefunden) und die Schnittstelle kann nicht geladen werden. Bitte installieren Sie diese Anwendung neu oder reparieren Sie sie.",
    "22355": "Freunde einladen und Preise für beide Seiten gewinnen · Unbegrenztes Kontingent für 4 Freunde",
    "22356": "Jedes Mal, wenn Sie eine Person einladen, erhalten Sie {firecores} Fireflies + {bonus} Kontingent. Sammeln Sie 400 Glühwürmchen und Sie können sie dauerhaft gegen ein unbegrenztes Kontingent eintauschen.",
    "22357": "4. Freund",
    "22916": "Die KI-Richtlinie wurde im aktuellen Arbeitsbereich nicht konfiguriert und der Eintritt in die Warteschlange wurde blockiert. Bitte schließen Sie zunächst die Arbeitsbereichskonfiguration ab.",
    "22918": "{count} Elemente wurden hinzugefügt und {blocked} Elemente wurden übersprungen, da der Arbeitsbereich noch keine Richtlinien konfiguriert hat.",
    "22919": "Keine neue Datei hinzugefügt (die Datei befindet sich möglicherweise bereits in der Warteschlange oder wurde analysiert)",
    "22920": "Firefly-Beamter",
    "22921": "Jailbreak-Bilderkennung",
    "22922": "LFM3-VL 2B ist ein fein abgestimmtes multimodales Modell mit Jailbreak, das leichtgewichtig ist und ein tiefes Bild- und Textverständnis unterstützt.",
    "22923": "Hohe Kostenleistung",
    "22924": "Für den aktuellen Arbeitsbereich ist keine KI-Richtlinie konfiguriert und die Analyse ist angehalten. Bitte schließen Sie zunächst die Arbeitsbereichskonfiguration ab.",
    "22925": "Gehen Sie zur Konfiguration",
    "22926": "Benutzeroberflächen- und Anzeigeeinstellungen",
    "22927": "Darstellung, Sprache, Thema und Dateilistenanzeige",
    "22931": "Arbeitsbereichskonfiguration, Analysetiefe und Katalogverwaltung",
    "22932": "Überblick über visuelle semantische Suche, multimodale Indexpflege und Arbeitsbereichsstrategien",
    "22934": "Tipp: Es wurde festgestellt, dass Sie die internationale Version installiert haben. Historische Daten werden im Originalverzeichnis gespeichert und die Daten in den beiden Regionen sind unabhängig voneinander.",
    "22935": "Tipp: Es wurde festgestellt, dass Sie die Inlandsversion bereits installiert haben. Die historischen Daten werden im Originalverzeichnis gespeichert. Die Daten in den beiden Bereichen sind unabhängig voneinander.",
    "22936": "Klicken Sie hier, um die aktuelle KI-Strategie und den Analysemodus für den Arbeitsbereich zu konfigurieren: {name}",
    "22937": "Klicken Sie hier, um die Arbeitsbereichskonfiguration zu öffnen",
    "22938": "Die bevorzugte Vorschau ist nicht verfügbar und wurde auf umgestellt",
    "22939": "Auf alternative Vorschau umgestellt",
    "22940": "Nochmals versuchen",
    "22941": "Die aktuelle Vorschau wird nicht normal gerendert und versucht, ein Downgrade durchzuführen ...",
    "22942": "Jetzt konfigurieren, um die Analyse zu aktivieren ➔",
    "22943": "Der aktuelle Arbeitsbereich hat die KI-Analyserichtlinie nicht bestätigt und die Dateianalyse wurde blockiert.",
    "22945": "Bitte wählen oder erstellen Sie zunächst links ein neues Arbeitsverzeichnis.",
