    "22949": "Es liest hauptsächlich Texte, Daten und Tabellen, analysiert schnell und spart Strom und eignet sich für häufiges Lesen und Dokumentenmanagement.",
    "22951": "Verstehen Sie den Bilderrahmen und die Hauptfarben und finden Sie Bilder bequemer. Es eignet sich für Illustrationen und Designmaterialien.",
    "22953": "Erkennen Sie Videogespräche automatisch und erfassen Sie Schlüsselbilder, um die Bearbeitung zu erleichtern und Clips zu finden, die für lange und kurze Videos geeignet sind.",
