    "23008": "Rein lokale Offline-Inferenz · Daten-Backhaul ohne Datenschutz",
    "23009": "Firefly AI Folder ist die persönliche Arbeit eines Software-Freaks. Gerne können Sie uns Ihre Erfahrungen und Ihr Feedback mitteilen.",
