    "23011": "Die Wartung des semantischen Index ist abgeschlossen",
    "23012": "Ausnahme bei der Pflege des semantischen Indexes: {msg}",
    "23014": "Verwalten Sie den globalen visuellen semantischen Abruf, die Pflege multimodaler Indizes oder gehen Sie zu jedem Arbeitsbereich, um exklusive Szenenstrategien zu konfigurieren.",
    "23015": "Die Analysestrategie wurde auf „arbeitsbereichsspezifische Konfiguration“ aktualisiert.",
    "23016": "Adaptive Architektur",
    "23017": "Low-Level-Parameter wie Analysemodus, Videobildbudget, OCR-Genauigkeit und Vektordimension wurden vollständig in das Arbeitsbereichssystem integriert. Das System kann basierend auf der Verzeichnisdateistruktur automatisch „Extrem schnelle Organisation“, „Kreative Galerie“, „Videomaterialien“ oder „Desktop-Downloads“ empfehlen. Jedes Verzeichnis ist unabhängig geschlossen und stört sich nicht gegenseitig.",
    "23018": "Konfigurieren Sie jeden Arbeitsbereich",
    "23019": "Visuelle semantische Suche (CLIP)",
    "23020": "Ermöglicht die Verwendung natürlichsprachlicher Beschreibungen von Bildern (z. B. „roter Sportwagen“, „Sonnenuntergang am Meer“), um Bildinhalte arbeitsbereichsübergreifend abzurufen.",
