    "23301": "{count} Zielerweiterungen wurden festgelegt. Nur Dateien mit diesen Erweiterungen dürfen nach dem Speichern in die KI-Analysewarteschlange gelangen.",
    "23303": "Ausschlüsse hinzufügen",
    "23304": "Fügen Sie Verzeichnisausschlussregeln hinzu",
    "23305": "Übereinstimmungstyp",
    "23306": "Übereinstimmungswert",
    "23307": "Geben Sie einen Namen oder ein Muster zum Ausschließen ein",
    "23308": "Bemerkungen (optional)",
    "23309": "Beispiel: lokales temporäres Kompilierungs-Build-Ausgabeverzeichnis",
    "23310": "Ausschlussregel speichern",
    "23311": "Derzeit gibt es keine exklusiven Ausschlussregeln für das aktuelle Arbeitsverzeichnis und richtet sich lediglich nach der unten aufgeführten globalen Systemgrundlinie.",
    "23312": "Wenn es in diesem Verzeichnis dedizierte temporäre Builds, Caches oder private Ordner gibt, die keiner Analyse bedürfen, können Sie oben auf „Ausschlüsse hinzufügen“ klicken.",
    "23313": "Löschen Sie diese Regel",
    "23315": "Gehen Sie zur Systemeinstellungsverwaltung",
    "23316": "Die folgenden Regeln gehören zur systemweiten Sicherheitslebensader (z. B. .git, node_modules, .VirtualDirectory usw.). Das aktuelle Verzeichnis wird automatisch von diesem geerbt und geschützt, und Verzeichnisregeln können Systemregeln nicht überschreiben oder aufheben.",
    "23317": "Die aktuelle Umgebung kann das lokale Verzeichnis nicht direkt öffnen",
    "23318": "Verzeichnis konnte nicht geöffnet werden",
    "23319": "Die automatische Überwachung wurde aktiviert: Neue Dateiänderungen werden automatisch zur KI-Analysewarteschlange hinzugefügt",
    "23320": "Die automatische Überwachung wurde angehalten: Änderungen an externen Dateien werden nicht mehr automatisch nachverfolgt",
    "23321": "Der Überwachungsstatus des Verzeichnisses konnte nicht aktualisiert werden",
    "23322": "Im aktuellen Verzeichnis sind keine neuen oder geänderten Dateien vorhanden",
    "23323": "Die Scanschnittstelle ist nicht verfügbar",
    "23324": "Das erneute Scannen des Verzeichnisses ist fehlgeschlagen",
    "23325": "Keine leeren Ordner gefunden, die Verzeichnisstruktur ist sehr übersichtlich!",
    "23326": "Das Scannen des leeren Ordners ist fehlgeschlagen",
    "23327": "Die Workspace-Analysedaten wurden sicher zurückgesetzt und die von anderen Verzeichnissen freigegebenen Dateien wurden gesetzeskonform vollständig aufbewahrt.",
    "23328": "Reset-Schnittstelle nicht erkannt",
    "23329": "Arbeitsbereichsausnahme zurücksetzen",
    "23330": "Das Arbeitsverzeichnis „{name}“ wurde aus der Anwendung entfernt",
    "23331": "Das Arbeitsverzeichnis konnte nicht entfernt werden",
    "23332": "Arbeitsverzeichnisausnahme entfernen",
    "23333": "Die Bindung des Workflows wurde aufgehoben und der aktuelle Whitelist-Snapshot wurde sicher aufbewahrt.",
    "23334": "Die Bindung des Workflows konnte nicht aufgehoben werden",
    "23335": "Unbinding-Workflow-Ausnahme",
    "23336": "Die Whitelist wurde gelöscht und ist wieder im Standard-Vollzulassungsmodus.",
    "23337": "Leere Liste konnte nicht gelöscht werden",
    "23338": "Leere Listenausnahme löschen",
    "23339": "Verzeichnispflege und -verwaltung",
    "23340": "Überwachen Sie Dateiänderungen, führen Sie einen vollständigen Scan durch, bereinigen Sie leere Ordner oder setzen Sie die KI-Analysedaten des aktuellen Verzeichnisses zurück.",
    "23341": "Zu konfigurieren",
    "23342": "Sehen Sie sich diesen Ordner im Betriebssystem-Explorer an",
    "23343": "Ordner öffnen",
    "23344": "Szenenabsicht:",
    "23345": "Bindungsworkflow:",
    "23346": "Ungebunden (Standardmodus)",
    "23347": "Hinzugefügte Zeit:",
    "23348": "Dateiänderungen automatisch überwachen (Auto Watch)",
    "23349": "Überwachung in Echtzeit",
    "23350": "Erkennen Sie neue, geänderte und gelöschte Dateien im aktuellen Verzeichnis in Echtzeit. Nach dem Öffnen werden neue Dateien automatisch synchronisiert und der intelligenten KI-Analysewarteschlange hinzugefügt.",
    "23351": "Erneutes Scannen und Änderungserkennung",
    "23352": "Führen Sie einen vollständigen Vergleich der physischen Festplattendateien durch, um zu prüfen, ob offline neue Dateien oder Änderungen hinzugefügt wurden, und verschieben Sie diese optional in die Analysewarteschlange.",
    "23353": "Erneut scannen",
    "23354": "Leere Ordner scannen und bereinigen",
    "23355": "Durchsuchen Sie das aktuelle Verzeichnis rekursiv nach leeren Ordnern, die nach dem Sortieren oder Löschen übrig geblieben sind. Es unterstützt die Anzeige von Details und die Stapelbereinigung mit einem Klick.",
    "23357": "Führen Sie den Szenario-Setup-Assistenten erneut aus",
    "23358": "Starten Sie den Minimalist-Assistenten neu und das System erkennt den Verzeichnisinhalt erneut und gibt Standardempfehlungen für „Schnelle Organisation/Kreative Galerie/Videomaterialien/Desktop-Unordnung“.",
    "23359": "Assistent ausführen",
    "23360": "Workflow-Bindung und Whitelist-Snapshot-Schutz",
    "23361": "Gebunden: {name}",
    "23362": "Ungebunden (generischer Modus)",
    "23366": "Workflow entbinden",
    "23368": "Gehen Sie zum Bindungsworkflow",
    "23369": "Schnappschuss der geltenden Erweiterung:",
    "23370": "Kataloganalysedaten sicher zurücksetzen",
    "23371": "Löschen Sie die AI-Tags, den Storyboard-Cache und den Textindex aller Dateien im aktuellen Verzeichnis. Geschützt durch den arbeitsbereichsübergreifenden Waisenschutzmechanismus werden freigegebene Dateien niemals versehentlich beschädigt.",
    "23372": "Daten zurücksetzen...",
    "23373": "Entfernen Sie das Arbeitsverzeichnis aus der Anwendung",
    "23374": "Heben Sie die Bindung dieses Verzeichnisses innerhalb der Anwendung auf und löschen Sie seine Indexdatensätze. Dieser Vorgang wirkt sich überhaupt nicht auf die tatsächlichen Dateien auf der physischen Festplatte aus und löscht diese auch nicht.",
    "23375": "Verzeichnis entfernen...",
    "23376": "Sicheren Reset „{name}“ bestätigen?",
    "23377": "Durch diesen Vorgang werden die Ergebnisse der KI-Analyse und der Storyboard-Cache aller Dateien im aktuellen Verzeichnis gelöscht, die tatsächlichen Dateien auf der physischen Festplatte werden jedoch nicht gelöscht.",
    "23378": "Geschützt durch den Waisenschutzmechanismus: Freigegebene Dateien, auf die von anderen Arbeitsbereichen verwiesen wird, werden automatisch durch Immunretention geschützt.",
    "23379": "Bestätigen Sie den sicheren Reset",
    "23380": "Sind Sie sicher, dass Sie das Arbeitsverzeichnis „{name}“ entfernen möchten?",
    "23381": "Möchten Sie dieses Arbeitsverzeichnis wirklich aus der App entfernen? Relevante Dateiindizierungs- und Analysedaten werden bereinigt.",
    "23382": "Sicher und geschützt: Dateien und Ordner auf der physischen Festplatte sind zu 100 % intakt.",
    "23383": "Bestätigen Sie das Entfernen",
    "23384": "Sind Sie sicher, dass Sie die Bindung des Workflows aufheben?",
    "23385": "Nach dem Aufheben der Workflow-Bindung wechselt das Verzeichnis in den allgemeinen Verwaltungsmodus und unterliegt nicht mehr bestimmten Workflow-Regeln.",
    "23387": "Bindung aufheben (Schnappschuss behalten)",
    "23391": "Löschen Sie die leere Liste und stellen Sie die volle Kapazität wieder her",
