    "27064": "Reisfeld",
    "27065": "Der exklusive Geschäftsworkflow wurde gebunden. Nach dem Aufheben der Bindung kehrt das Verzeichnis in den Universalmodus zurück und Snapshots mit Regeln werden automatisch beibehalten, um den Zustrom von Nicht-Zieldateien zu verhindern.",
