    "30519": "Leichte CPU-Engine",
    "30521": "Ihr Gerät verfügt über weniger als 4 GB Videospeicher. Es wird empfohlen, eine leichte CPU-Engine zu verwenden.",
    "30523": "Der Motorwechsel läuft (wartet länger als 3 Sekunden), Sie können weiter warten oder sofort abbrechen.",
