    "30526": "Serviceanomalie (Sicherungsschutz)",
    "30527": "Der Motor ist ständig abnormal ausgefallen und das automatische Laden wurde ausgesetzt; Klicken Sie auf [Modell vorheizen], um das Zurücksetzen ein zweites Mal zu bestätigen.",
    "30528": "Nicht genügend Speicher, pausiert",
    "30529": "Der aktuell verfügbare Speicher des Computers ist niedrig und der Inferenzdienst wurde ausgesetzt, um einen reibungslosen Betrieb des Systems zu gewährleisten.",
    "30530": "Das Laden ist fehlgeschlagen",
    "30531": "Die Modelldatei ist abnormal oder die Laufzeitanalyse schlägt fehl. Klicken Sie bitte, um die Selbstprüfung erneut durchzuführen.",
    "30532": "Modell wird geladen (dauert schätzungsweise 1 bis 3 Sekunden) ...",
    "30533": "Vorbereitung des Hochgeschwindigkeitsmodells im Speicher, fast fertig",
