    "30535": "Modell nicht geladen (wird bei der ersten Verwendung automatisch geladen)",
    "30536": "Derzeit im Leerlauf-Zero-Memory-Modus, wird es sofort automatisch aktiviert, wenn das Umbenennen oder Markieren eingeleitet wird.",
    "30537": "Das leichte CPU-Modell ist aufgewärmt und bereit",
