    "30551": "Unabhängiger Absturzschutz · Die Kernvolltextsuche ist nicht betroffen",
    "30552": "Unterstützte Missionsfähigkeiten:",
    "30553": "Intelligente Extraktion von Dateinamen, kontrollierte semantische Kennzeichnung und Bewertung der Dateiqualität.",
    "30554": "💡 Komplexe Aufgaben wie die Planung der Verzeichnisrekonstruktion erfordern tiefergehende, mehrstufige Überlegungen. Wählen Sie bei Bedarf bitte die erweiterte Firecore-Engine oder die Cloud-Engine.",
    "30555": "Versuchen Sie erneut, das Lightweight-CPU-Modell zu laden?",
    "30556": "Es wurde festgestellt, dass dieses Modell auf Ihrem Gerät zweimal hintereinander abnormal beendet wurde und das System eine Sicherheitssicherung ausgelöst hat. Durch Bestätigen des Fortfahrens wird der Absturzzähler gelöscht und die Modelllastprüfung erneut ausgeführt.",
    "30557": "Ich versuche es noch nicht",
    "30558": "Bestätigen Sie das Neuladen",
    "30559": "Dies wurde in den globalen Regeln ausgeschlossen und muss im aktuellen Verzeichnis nicht wiederholt hinzugefügt werden.",
    "30560": "Hier werden nur Elemente angezeigt, die im aktuellen Verzeichnis ausgeschlossen werden müssen. Elemente, die in globalen Regeln ausgeschlossen wurden, werden hier nicht wiederholt.",
    "30561": "{count} Ausschlüsse, die Duplikate globaler Regeln waren, wurden automatisch zusammengeführt und bleiben in Kraft.",
    "31288": "Unbegrenzte private Verzeichnisse freischalten (kann durch Einladen von 4 Freunden freigeschaltet werden)",
    "31289": "Die Überprüfung der Plug-in-Signatur ist fehlgeschlagen. Das Installationspaket wurde möglicherweise beschädigt oder illegal manipuliert und wurde sicher beendet.",
    "31290": "Das Plug-in-Kernmodell oder die Überprüfung der Ressourcendatei ist inkonsistent. Die Datei ist möglicherweise beschädigt. Bitte laden Sie es herunter oder laden Sie es erneut herunter.",
    "31292": "Es wurde erkannt, dass eine gleichwertige oder höhere Version des Plug-Ins bereits installiert ist und keine Neuinstallation erforderlich ist.",
    "31293": "Die vom Plug-in benötigten Ressourcen weisen Versionskonflikte mit vorhandenen Komponenten auf und können nicht direkt überschrieben werden.",
