    "31330": "Die Datei wird von anderen Programmen belegt. Bitte schließen Sie die entsprechende Anwendung und versuchen Sie es erneut.",
    "31331": "Classic Light KI-Engine (Classic Light)",
    "31332": "Grundlegende KI-Engine",
    "31333": "[Dateien und Bilder nach Bedeutung suchen] Suchen Sie schnell nach Fotos und Dokumenten basierend auf der allgemeinen Bedeutung Ihrer Beschreibung. Da sie nur sehr wenig Speicher beanspruchen, können selbst alte Computer und dünne und leichte Notebooks der unteren Preisklasse reibungslos laufen. Unterstützt kein Audio und Video",
    "31334": "Extrem geringer Konfigurationsaufwand · Die erste Wahl für alte Computer und dünne und leichte Laptops",
    "31335": "Einheitliche, vollmodale KI-Engine (Gemma Unified)",
    "31336": "[Intelligenteres Allround-Suchgehirn] Es kann komplexe Sätze, Bilder, Audios und Videos tiefer und genauer verstehen und Ihre Gedanken bei der Suche nach Dingen besser verstehen. Empfohlen für Computer mit 8 GB oder mehr Speicher.",
    "31337": "Empfohlene Konfiguration · Computerspeicher 8 GB oder mehr",
    "31338": "Leichte CPU-generative Engine (Pocket-CPU)",
    "31339": "[Standard auf dünnen und leichten Büro-Laptops] Unterstützt die intelligente Tiefenreinigung von Dateinamen, die Extraktion von Beschreibungen und die Tiefenanalyse von Inhalten. Dieses Plug-in ist nicht erforderlich, wenn die Firecore-Engine aktiviert ist.",
    "31340": "Extrem niedrige Konfigurationsanforderungen · Reiner CPU-Betrieb",
    "31341": "Identifizierung sensibler Inhalte und NSFW-Bewertung",
    "31342": "Extraktion von Dateiinhalten",
    "31343": "[Markierung privater und sensibler Bilder und Texte] Identifizieren Sie automatisch private und sensible Bilder und Dokumente/AIGC-Texte mit expliziten und sensiblen Beschreibungen und markieren Sie sie, um Peinlichkeiten bei der Anzeige auf einem Bildschirm zu vermeiden. Alle Computer laufen extrem schnell.",
    "31344": "Minimale Konfigurationsanforderungen · Extrem schnelle Verarbeitung",
    "31345": "Spracherkennung und Untertitelextraktion ASR (SenseVoice)",
    "31346": "[Aufzeichnungen und Videos automatisch in Text umwandeln] Verstehen Sie den Sprachinhalt in Videos und Aufzeichnungen und extrahieren Sie Untertitel. Sie können direkt nach „Wer hat einen bestimmten Satz gesagt“ suchen? Es verbraucht mehr Rechenleistung, daher werden 16 GB Arbeitsspeicher oder eine Grafikkarte empfohlen.",
    "31347": "Mehr Rechenleistung erforderlich · 16 GB Speicher oder Grafikkarte empfohlen",
    "31348": "Personalisiertes Voice-Clone-Lesen (Moss-TTS)",
    "31349": "[Unterstützt das Klonen exklusiver Stimmen] Integrierter Sound-Extraktor, laden Sie eine Aufnahme hoch, um exklusive Stimmen zum Lesen von Artikeln zu klonen. Unterstützt über 50 handverlesene Sounds und benutzerdefinierte Klone.",
    "31350": "Geringe Konfigurationsanforderungen · Normaler Computer für reibungslose Aussprache",
    "31351": "Extrem schnelles und leichtes Sprachlesen (M5-TTS)",
    "31352": "[Extrem schnelles und stromsparendes Lesen] Drücken Sie Play und der Ton beginnt sofort in Millisekunden. Es sind mehr als 50 reichhaltige und hochwertige Stimmen integriert, und lange Dokumente können reibungslos und ohne Verzögerung vorgelesen werden. Gewöhnliche dünne und leichte Notebooks laufen flüssig.",
    "31353": "Extrem geringe Konfigurationsanforderungen · Reibungslose Aussprache für gewöhnliche dünne und leichte Notebooks",
    "31354": "Lokales Kartierungsstudio",
    "31355": "[Bilder lokal auf Ihrem Computer zeichnen] Geben Sie einen Satz ein, um lokal schöne Bilder zu zeichnen, ohne einen Cent auszugeben. Erfordert eine bessere separate Grafikkarte.",
    "31356": "Höhere Konfiguration · Erfordert separate Grafikkarte",
    "31357": "Komprimierte Paketperspektive und Tiefenparser",
    "31358": "[Komprimiertes Paket direkt ohne Dekomprimierung durchsuchen] Sie können den Dateiinhalt in der ZIP-/RAR-Datei direkt anzeigen und durchsuchen, ohne sie zu dekomprimieren, ohne zusätzliche Computerbelastung.",
    "31359": "Minimale Konfigurationsanforderungen · Keine zusätzliche Belastung",
