    "31429": "[Ultraleichte und extrem schnelle Aussprache] Sprechen Sie das erste Wort in Millisekunden aus, mit nur ~350 MB Speicher, sodass es auf gewöhnlichen dünnen und leichten Notebooks reibungslos und reibungslos funktioniert.",
    "31430": "51 ausgewählte gute Sounds · Sofort einsatzbereit",
    "31431": "Durchsuchen Sie die 51 vorgestellten Sounds, hören Sie sie sich an und fügen Sie Ihre Favoriten zu Ihrer schnellen Sammlung hinzu.",
    "31432": "Suchen Sie nach dem Namen, der Sprache, dem charakteristischen Stil oder der Emotion des Sprechers (z. B. Zhu Mei, Yun Hope, Shen Wen) ...",
    "31433": "Gesammelt",
    "31434": "Als Standard festlegen",
