    "31442": "Basierend auf dem aktuellen Verzeichnisscan wird erwartet, dass {matchedCount} / {totalFiles}-Dateien angezeigt werden (die verbleibenden {hiddenCount} nicht solchen Dateien werden sicher ausgeblendet und die Originaldateien auf der Festplatte werden niemals geändert).",
